'use strict';
// ============================================================================
// Фикстура свечей для тестов индикаторов.
//
// Серия подобрана НЕ случайно:
//  • цена и растёт, и падает — иначе RSI/стохастик упираются в 0 или 100 и
//    любая формула «проходит»;
//  • close не по центру диапазона high/low — иначе множитель денежного потока
//    (A/D, CMF) тождественно ноль, и объёмные индикаторы нечем сломать;
//  • объёмы разные — иначе OBV и VWAP вырождаются в счётчик и в среднюю цену;
//  • есть свечи с гэпом к предыдущему close — иначе True Range всегда равен
//    high−low, и две из трёх его ветвей никогда не выполняются.
// ============================================================================
const CANDLES = [
  { time: 1000, open: 10.0, high: 11.0, low: 9.5, close: 10.5, volume: 100 },
  { time: 1060, open: 10.5, high: 12.0, low: 10.2, close: 11.8, volume: 140 },
  { time: 1120, open: 11.8, high: 12.4, low: 11.0, close: 11.2, volume: 90 },
  { time: 1180, open: 11.2, high: 11.5, low: 9.8, close: 10.0, volume: 200 },
  { time: 1240, open: 10.0, high: 10.6, low: 9.0, close: 9.3, volume: 180 },
  { time: 1300, open: 9.3, high: 11.4, low: 9.1, close: 11.2, volume: 260 },
  { time: 1360, open: 11.2, high: 13.0, low: 11.1, close: 12.9, volume: 300 },
  { time: 1420, open: 12.9, high: 13.2, low: 12.0, close: 12.2, volume: 120 },
  { time: 1480, open: 12.2, high: 14.5, low: 12.1, close: 14.3, volume: 340 },
  { time: 1540, open: 14.3, high: 14.6, low: 13.2, close: 13.5, volume: 160 },
  { time: 1600, open: 13.5, high: 15.8, low: 13.4, close: 15.6, volume: 380 },
  { time: 1660, open: 15.6, high: 15.9, low: 14.7, close: 15.0, volume: 110 },
];

const CLOSES = CANDLES.map((c) => c.close);

module.exports = { CANDLES, CLOSES };
